.327469],[42.170269,0.327249],[42.170293,0.327168],[42.170391,0.327185],[42.170491,0.327244],[42.17064,0.327359],[42.170778,0.327493],[42.170876,0.327658],[42.170968,0.327805],[42.171066,0.32792],[42.171103,0.327988],[42.171083,0.328109],[42.170989,0.328205],[42.170953,0.328282],[42.171014,0.328354],[42.171089,0.328392],[42.17115,0.328519],[42.17123,0.328741],[42.171256,0.328853],[42.171331,0.328869],[42.171351,0.329013],[42.171235,0.329208],[42.171096,0.32946],[42.17106,0.329526],[42.171038,0.329656],[42.171034,0.329911],[42.171051,0.330113],[42.171173,0.330449],[42.171276,0.330702],[42.171389,0.330908],[42.171472,0.331001],[42.171597,0.331113],[42.171733,0.331271],[42.171873,0.331463],[42.172162,0.331863],[42.172269,0.331961],[42.172342,0.331987],[42.172449,0.331957],[42.172543,0.331965],[42.172817,0.33221],[42.172894,0.332247],[42.173029,0.332265],[42.173335,0.332243],[42.173655,0.332196],[42.173976,0.332165],[42.174187,0.332158],[42.174337,0.332177],[42.174453,0.332224],[42.17478,0.33244],[42.175055,0.332671],[42.176447,0.3339],[42.177622,0.334914],[42.178254,0.335373],[42.17883,0.33559],[42.179385,0.335612],[42.179803,0.335566],[42.180315,0.335505],[42.18066,0.335505],[42.181006,0.335543],[42.181624,0.335671],[42.182718,0.335945],[42.183813,0.336195],[42.184611,0.336447],[42.184828,0.336511],[42.185215,0.336628],[42.185277,0.336648],[42.185813,0.336829],[42.186826,0.337173],[42.186985,0.337224],[42.187442,0.337386],[42.187956,0.33757],[42.188456,0.337738],[42.188737,0.33784]]$coords$::jsonb;
  v_route record;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_invalid integer;
  v_start_gap_m double precision;
  v_end_gap_m double precision;
begin
  select jsonb_agg(jsonb_build_object(
    'lat',(point->>0)::double precision,
    'lon',(point->>1)::double precision
  ) order by ordinality)
    into v_points
    from jsonb_array_elements(v_coords)
      with ordinality as p(point,ordinality);
  select h.id,h.latitude,h.longitude,h.published,h.trace_available,
      h.official_url,h.description,h.distance_km,
      t.status,t.segments,t.geometry_source_url,t.official,t.continuity_checked
    into v_route
    from public.hiking_routes h
    join public.hiking_route_tracks t on t.route_id=h.id
    where h.id='osm-relation-4161862'
      and h.source='openstreetmap'
      and h.name='Olvena-La Puebla de Castro-Graus'
      and h.route_ref='PR-HU 73'
      and h.raw_tags->>'ref'='PR-HU 73'
      and h.source_url='https://www.openstreetmap.org/relation/4161862'
      and h.official_url in (
        'http://senderos.turismoribagorza.org/ficha.php?id_ruta=101',
        'https://turismoribagorza.org/ruta/pr-hu-73-olvena-la-puebla-de-castro-graus/')
      and exists (select 1 from public.hiking_route_regions r
        where r.route_id=h.id and r.region_code='huesca' and r.published)
    for update of h,t;
  if not found then
    raise exception 'PR-HU 73 route identity or published region changed';
  end if;
  if v_route.status='ready' then
    if v_route.geometry_source_url='https://turismoribagorza.org/wp-content/uploads/2025/06/29_pr_hu_73.gpx'
      and v_route.segments=jsonb_build_array(v_points)
      and v_route.official and v_route.continuity_checked
      and v_route.published and v_route.trace_available
      and v_route.official_url='https://turismoribagorza.org/ruta/pr-hu-73-olvena-la-puebla-de-castro-graus/'
      and v_route.distance_km=14.53 then
      return;
    end if;
    raise exception 'PR-HU 73 route has another ready trace or publication state';
  end if;
  if v_route.status<>'missing' or v_route.published or v_route.trace_available
    or v_route.segments is not null or v_route.geometry_source_url is not null
    or v_route.description is not null or v_route.distance_km is not null then
    raise exception 'PR-HU 73 hidden route state changed';
  end if;
  with points as (
    select ordinality idx,(point->>0)::double precision lat,
      (point->>1)::double precision lon
    from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality)
  ), steps as (
    select *,lag(lat) over(order by idx) prev_lat,
      lag(lon) over(order by idx) prev_lon from points
  ), distances as (
    select case when prev_lat is null then 0 else
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(prev_lon,prev_lat))/1000 end step_km,
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(v_route.longitude,v_route.latitude))/1000 center_km,
      (lat between 42.10 and 42.20 and lon between 0.23 and 0.34) valid
    from steps
  )
  select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
    coalesce(min(center_km),999),count(*) filter(where not valid)
    into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
    from distances;
  select ST_DistanceSphere(
    ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
    ST_MakePoint(0.260711,42.107715)),
    ST_DistanceSphere(
    ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,
      (v_coords->(v_count-1)->>0)::double precision),
    ST_MakePoint(0.33784,42.188737))
    into v_start_gap_m,v_end_gap_m;
  if v_count<>745 or v_invalid>0
    or abs(v_length_km-14.526786)>0.015
    or v_max_gap_km>0.186 or v_center_gap_km>0.9
    or v_start_gap_m>2 or v_end_gap_m>2 then
    raise exception 'PR-HU 73 GPS validation failed: points %, length %, gap %, center %, start %, end %, invalid %',
      v_count,v_length_km,v_max_gap_km,v_center_gap_km,
      v_start_gap_m,v_end_gap_m,v_invalid;
  end if;
  update public.hiking_route_tracks
    set status='ready',segments=jsonb_build_array(v_points),checked_at=now(),
      continuity_checked=true,
      geometry_source='Comarca de Ribagorza - GPX oficial PR-HU 73',
      geometry_source_url='https://turismoribagorza.org/wp-content/uploads/2025/06/29_pr_hu_73.gpx',official=true
    where route_id=v_route.id and status='missing';
  if not found then
    raise exception 'PR-HU 73 track state changed';
  end if;
  update public.hiking_routes
    set trace_available=true,published=true,
      distance_km=round(v_length_km::numeric,2),route_type='Lineal',
      duration_minutes=250,ascent_m=240,
      official_url='https://turismoribagorza.org/ruta/pr-hu-73-olvena-la-puebla-de-castro-graus/',
      description='PR-HU 73 de Olvena a Graus por La Puebla de Castro. Recorrido lineal con 14,53 km en el GPX oficial. La ficha de la Comarca de Ribagorza indica 14,64 km, 4 h 10 min y 240 m de subida. El trazado conserva los puntos del archivo oficial, incluidos sus tramos rectos de menor densidad.'
    where id=v_route.id and not published and not trace_available;
  if not found then
    raise exception 'PR-HU 73 publication state changed';
  end if;
end
$curate$;
